{"packet_id":"D079-01","doc_id":"D079","jurisdiction":"San Francisco, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Francisco Rent Ordinance just cause eviction","requirement":"A landlord may evict a tenant in a rental unit covered by the Rent Ordinance only for one of the 17 just cause reasons in Section 37.9(a); expiration of the rental agreement or a change of ownership is not just cause.","key_value":"17 just cause reasons","coverage_conditions":"Rental units covered by the Rent Ordinance. Tenancies exempt from the Ordinance's rent increase limits (units first certified for occupancy after June 13, 1979, Costa-Hawkins-eligible tenancies, rent regulated by another agency) are still subject to the eviction provisions.","applicability":{"conditions":[{"type":"other","text":"rental unit covered by the Rent Ordinance"}],"per_tenancy":"Applies to tenancies in covered rental units, including tenancies exempt from the Ordinance's rent increase limits.","coverage_quotes":["In order to evict a tenant from a rental unit covered by the Rent Ordinance, a landlord must have a \"just cause\" reason that is the dominant motive for pursuing the eviction."]},"exemptions":null,"penalty":"If a landlord evicts or tries to evict a tenant unlawfully, the landlord may be subject to substantial civil and/or criminal liability.","effective_date":null,"valid_through":null,"citation":"S.F. Admin. Code § 37.9","quoted_span":"In order to evict a tenant from a rental unit covered by the Rent Ordinance, a landlord must have a \"just cause\" reason that is the dominant motive for pursuing the eviction. Note that the mere expiration of a rental agreement or a change in ownership does not constitute \"just cause\" for eviction.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D079-01","doc_id":"D079","jurisdiction":"San Francisco, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"San Francisco Rent Ordinance rent increase limitation exemptions","requirement":"The Rent Ordinance's limits on rent increases do not apply to tenancies in newly constructed rental units first certified for occupancy after June 13, 1979, to tenancies eligible for an increase under the Costa-Hawkins Rental Housing Act, or to some tenancies whose rent another agency regulates.","key_value":null,"coverage_conditions":"Tenancies exempt from the Ordinance's rent increase limitations: units that first obtained a Certificate of Occupancy after June 13, 1979, Costa-Hawkins-eligible tenancies, and tenancies where the rent is regulated by another government agency.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1979-06-13","basis":"certificate_of_occupancy"},{"type":"other","text":"rent regulated by another government agency"}],"per_tenancy":"Tenancies eligible for a rent increase under the Costa-Hawkins Rental Housing Act.","coverage_quotes":["This includes tenancies in newly constructed rental units that first obtained a Certificate of Occupancy after June 13, 1979, tenancies that are eligible for a rent increase under the Costa-Hawkins Rental Housing Act, and some tenancies where the rent is regulated by another government agency."]},"exemptions":"Tenancies in units first certified for occupancy after June 13, 1979; tenancies eligible for a rent increase under the Costa-Hawkins Rental Housing Act; some tenancies whose rent is regulated by another government agency.","penalty":null,"effective_date":null,"valid_through":null,"citation":"S.F. Admin. Code ch. 37","quoted_span":"This includes tenancies in newly constructed rental units that first obtained a Certificate of Occupancy after June 13, 1979, tenancies that are eligible for a rent increase under the Costa-Hawkins Rental Housing Act, and some tenancies where the rent is regulated by another government agency.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
